              transition: {
                staggerChildren: 0.09,
              },
            },
          }}
        >
          <div className='columns-2 gap-4 px-8 sm:columns-3'>
            {[
              '/labs/references/motion-primitives/media-placeholder.svg
              '/labs/references/motion-primitives/media-placeholder.svg
              '/labs/references/motion-primitives/media-placeholder.svg
              '/labs/references/motion-primitives/media-placeholder.svg
              '/labs/references/motion-primitives/media-placeholder.svg
              '/labs/references/motion-primitives/media-placeholder.svg
              '/labs/references/motion-primitives/media-placeholder.svg
              '/labs/references/motion-primitives/media-placeholder.svg
